/*
 * Runtime contract for code generated by mipsrecomp.
 *
 * Compile generated code with: -fno-thread-jumps -fwrapv -fno-strict-aliasing -ffp-contract=off -fno-math-errno
 * (guest memory is accessed through casted pointers; guest FP is IEEE single/double
 * with separate rounding of multiply and add).
 */
#ifndef RECOMP_H
#define RECOMP_H

#include <stdint.h>

#ifndef RC_MEM_SIZE
#define RC_MEM_SIZE (32u << 20) /* flat guest RAM, power of two */
#endif
#define RC_MEM_MASK (RC_MEM_SIZE - 1u)
#define RC_STACK_TOP (RC_MEM_SIZE - 0x10000u)

typedef struct rc_ctx {
  uint32_t r[32];
  uint32_t hi, lo;
  uint32_t f[32]; /* FR=0: doubles occupy even/odd pairs, low word in the even register */
  uint32_t fcr31;
  uint32_t tls;
  uint32_t pc; /* only updated at syscalls / traps, for diagnostics */
} rc_ctx;

typedef void (*rc_func)(rc_ctx *ctx);
typedef struct {
  uint32_t addr;
  rc_func fn;
  const char *name;
} rc_func_entry;
typedef struct {
  uint32_t vaddr, filesz, memsz;
  const uint8_t *data;
} rc_segment;

extern uint8_t *rc_mem;
extern const rc_func_entry rc_func_table[];
extern const unsigned rc_func_count;
extern const rc_segment rc_segments[];
extern const unsigned rc_segment_count;
extern const uint32_t rc_entry;

/* ---- guest memory (little-endian guest on little-endian host) ---- */
#define RC_ADDR(a) ((uint32_t)(a) & RC_MEM_MASK)
#define RC_P8(a) (rc_mem + RC_ADDR(a))
#define RC_LB(a) ((uint32_t)(int32_t)(int8_t)*RC_P8(a))
#define RC_LBU(a) ((uint32_t)*RC_P8(a))
#define RC_LH(a) ((uint32_t)(int32_t) * (int16_t *)RC_P8(a))
#define RC_LHU(a) ((uint32_t) * (uint16_t *)RC_P8(a))
#define RC_LW(a) (*(uint32_t *)RC_P8(a))
#define RC_SB(a, v) (*RC_P8(a) = (uint8_t)(v))
#define RC_SH(a, v) (*(uint16_t *)RC_P8(a) = (uint16_t)(v))
#define RC_SW(a, v) (*(uint32_t *)RC_P8(a) = (uint32_t)(v))

#define RC_ROTR(x, s) ((s) ? (((x) >> (s)) | ((x) << (32 - (s)))) : (x))
#define RC_CLZ(x) ((x) ? (uint32_t)__builtin_clz(x) : 32u)

static inline uint32_t rc_lwl(uint32_t a, uint32_t rt) {
  unsigned sh = 8 * (3 - (a & 3));
  uint32_t w = RC_LW(a & ~3u);
  return (w << sh) | (sh ? (rt & ((1u << sh) - 1)) : 0);
}
static inline uint32_t rc_lwr(uint32_t a, uint32_t rt) {
  unsigned sh = 8 * (a & 3);
  uint32_t w = RC_LW(a & ~3u);
  return (w >> sh) | (rt & ~(0xFFFFFFFFu >> sh));
}
static inline void rc_swl(uint32_t a, uint32_t rt) {
  unsigned sh = 8 * (3 - (a & 3));
  uint32_t w = RC_LW(a & ~3u);
  RC_SW(a & ~3u, (w & ~(0xFFFFFFFFu >> sh)) | (rt >> sh));
}
static inline void rc_swr(uint32_t a, uint32_t rt) {
  unsigned sh = 8 * (a & 3);
  uint32_t w = RC_LW(a & ~3u);
  RC_SW(a & ~3u, (w & (sh ? (1u << sh) - 1 : 0)) | (rt << sh));
}

/* ---- FPU register access ---- */
static inline float RC_FS(rc_ctx *c, int n) {
  float f;
  __builtin_memcpy(&f, &c->f[n], 4);
  return f;
}
static inline void RC_SET_FS(rc_ctx *c, int n, float v) { __builtin_memcpy(&c->f[n], &v, 4); }
static inline double RC_FD(rc_ctx *c, int n) {
  uint64_t bits = (uint64_t)c->f[n & ~1] | ((uint64_t)c->f[n | 1] << 32);
  double d;
  __builtin_memcpy(&d, &bits, 8);
  return d;
}
static inline void RC_SET_FD(rc_ctx *c, int n, double v) {
  uint64_t bits;
  __builtin_memcpy(&bits, &v, 8);
  c->f[n & ~1] = (uint32_t)bits;
  c->f[n | 1] = (uint32_t)(bits >> 32);
}

/* ---- legacy MIPS NaN semantics (pre-NaN2008) ----
 * Host FPUs produce 0x7fc00000-style NaNs; the guest expects the legacy MIPS
 * default NaN. Results are only touched on the (cold) NaN path. */
#define RC_DNAN_S 0x7fbfffffu
#define RC_DNAN_D 0x7ff7ffffffffffffull
static inline uint32_t rc_fbits(float f) { uint32_t b; __builtin_memcpy(&b, &f, 4); return b; }
static inline uint64_t rc_dbits(double d) { uint64_t b; __builtin_memcpy(&b, &d, 8); return b; }
static inline float rc_bitsf(uint32_t b) { float f; __builtin_memcpy(&f, &b, 4); return f; }
static inline double rc_bitsd(uint64_t b) { double d; __builtin_memcpy(&d, &b, 8); return d; }
static inline int rc_nan_s(uint32_t b) { return (b & 0x7fffffffu) > 0x7f800000u; }
static inline int rc_snan_s(uint32_t b) { return rc_nan_s(b) && (b & 0x00400000u); }
static inline int rc_nan_d(uint64_t b) { return (b & ~(1ull << 63)) > 0x7ff0000000000000ull; }
static inline int rc_snan_d(uint64_t b) { return rc_nan_d(b) && (b & (1ull << 51)); }

float rc_nan_pick_s(float a, float b, int nargs);
double rc_nan_pick_d(double a, double b, int nargs);
double rc_cvt_d_s(float a);
float rc_cvt_s_d(double a);

#define RC_FIX_S2(r, a, b) (__builtin_expect((r) == (r), 1) ? (r) : rc_nan_pick_s((a), (b), 2))
#define RC_FIX_D2(r, a, b) (__builtin_expect((r) == (r), 1) ? (r) : rc_nan_pick_d((a), (b), 2))
#define RC_FIX_S1(r, a) (__builtin_expect((r) == (r), 1) ? (r) : rc_nan_pick_s((a), (a), 1))
#define RC_FIX_D1(r, a) (__builtin_expect((r) == (r), 1) ? (r) : rc_nan_pick_d((a), (a), 1))

/* ---- register-promoted forms (guest registers held in C locals r1.., f0.., hi, lo, fcsr) ---- */
#define RC_LFS(n) rc_bitsf(f##n)
#define RC_LFD(e, o) rc_bitsd((uint64_t)f##e | ((uint64_t)f##o << 32))
#define RC_LSET_FS(n, v) (f##n = rc_fbits(v))
#define RC_LSET_FD(e, o, v)                                   \
  do {                                                        \
    uint64_t b_ = rc_dbits(v);                                \
    f##e = (uint32_t)b_;                                      \
    f##o = (uint32_t)(b_ >> 32);                              \
  } while (0)
/* QEMU semantics: a zero divisor, or INT_MIN / -1, is replaced by 1. */
#define RC_DIV(a, b)                                          \
  do {                                                        \
    int32_t x_ = (int32_t)(a), y_ = (int32_t)(b);             \
    if (y_ == 0 || (x_ == INT32_MIN && y_ == -1)) y_ = 1;     \
    lo = (uint32_t)(x_ / y_);                                 \
    hi = (uint32_t)(x_ % y_);                                 \
  } while (0)
#define RC_DIVU(a, b)                                         \
  do {                                                        \
    uint32_t x_ = (a), y_ = (b);                              \
    if (y_ == 0) y_ = 1;                                      \
    lo = x_ / y_;                                             \
    hi = x_ % y_;                                             \
  } while (0)
#define RC_CFC1(n) ((n) == 31 ? fcsr : (n) == 0 ? 0x00739300u : 0u)
#define RC_CTC1(n, v)                                         \
  do {                                                        \
    if ((n) == 31) fcsr = (v) & 0x0183FFFFu;                  \
  } while (0)

/* ---- runtime services (recomp_runtime.c) ---- */
void rc_syscall(rc_ctx *ctx);
void rc_dispatch(rc_ctx *ctx, uint32_t target, uint32_t from);
void rc_div(rc_ctx *ctx, uint32_t a, uint32_t b);
void rc_divu(rc_ctx *ctx, uint32_t a, uint32_t b);
int32_t rc_to_w(double v, unsigned mode);
uint32_t rc_cfc1(rc_ctx *ctx, int reg);
void rc_ctc1(rc_ctx *ctx, int reg, uint32_t v);
void rc_trace_enter(rc_ctx *ctx, uint32_t addr);
void rc_trace_insn(rc_ctx *ctx, uint32_t pc);
__attribute__((noreturn)) void rc_overflow(rc_ctx *ctx, uint32_t pc);
__attribute__((noreturn)) void rc_trap(rc_ctx *ctx, uint32_t pc);
__attribute__((noreturn)) void rc_break(rc_ctx *ctx, uint32_t pc, uint32_t code);
__attribute__((noreturn)) void rc_unknown(rc_ctx *ctx, uint32_t pc, uint32_t word);
__attribute__((noreturn)) void rc_fallthrough(rc_ctx *ctx, uint32_t pc);

int rc_run(void);

/* ---- platform layer (one implementation per target) ---- */
void *rc_platform_alloc_guest_ram(uint32_t size);
long rc_platform_write(int fd, const void *buf, uint32_t len);
__attribute__((noreturn)) void rc_platform_exit(int code);
/* Returns <0 for "not available" (mirrors -ENOSYS under qemu). */
long rc_platform_present(const uint8_t *rgba, uint32_t w, uint32_t h);
long rc_platform_buttons(void);
long rc_platform_ticks_us(void);
void rc_platform_log(const char *msg);

#endif
